```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int n;
    int ile = 0;
    while (plik >> n) {
        int parzyste = 0, nieparzyste = 0;
        int tmp = n;
        while (tmp > 0) {
            int c = tmp % 10;
            if (c % 2 == 0) parzyste++;
            else nieparzyste++;
            tmp /= 10;
        }
        cout << n << ": parzyste=" << parzyste << ", nieparzyste=" << nieparzyste;
        if (parzyste > nieparzyste) {
            cout << " -> wiecej parzystych" << endl;
            ile++;
        } else {
            cout << endl;
        }
    }
    cout << "Liczby z wiecej cyframi parzystymi: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Petla wyodrebnia cyfry od konca. Cyfra 0 jest parzysta (0%2==0). Porownanie licznikow decyduje o klasyfikacji.

